import json
import zipfile
import xml.etree.ElementTree as ET
from pathlib import Path
import bisect

src='/root/offer_letter_template.docx'
dst='/root/offer_letter_filled.docx'

data=json.load(open('/root/employee_data.json'))

replacements={k:str(v) for k,v in data.items()}

NS_W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'


def get_text_elements(tree):
    return [el for el in tree.iter() if el.tag == f'{{{NS_W}}}t']

def build_concat_and_starts(texts):
    starts=[]
    pos=0
    for t in texts:
        starts.append(pos)
        pos+=len(t)
    return ''.join(texts), starts

def apply_matches(texts, starts, matches):
    # matches: list of (start, end, replacement) positions based on original concat
    # apply from end to start
    matches=sorted(matches, key=lambda x: x[0], reverse=True)
    for s,e,repl in matches:
        if s is None or e is None:
            continue
        if s<0 or e<s:
            continue
        # find element indexes
        # if s == total length, skip
        if not starts:
            continue
        total_len = starts[-1] + len(texts[-1])
        if s>total_len:
            continue
        if e>total_len:
            e=total_len
        # map s and e-1
        i_start = bisect.bisect_right(starts, s) - 1
        if i_start < 0:
            i_start = 0
        if e == 0:
            i_end = 0
        else:
            i_end = bisect.bisect_right(starts, e-1) - 1
            if i_end < 0:
                i_end = 0
        start_offset = s - starts[i_start]
        end_offset = e - starts[i_end]
        if i_start == i_end:
            t=texts[i_start]
            texts[i_start]=t[:start_offset] + repl + t[end_offset:]
        else:
            t_start=texts[i_start]
            t_end=texts[i_end]
            prefix=t_start[:start_offset]
            suffix=t_end[end_offset:]
            texts[i_start]=prefix + repl
            for j in range(i_start+1, i_end):
                texts[j]=''
            texts[i_end]=suffix


def process_xml(xml_bytes, replacements, relocation_yes):
    tree = ET.fromstring(xml_bytes)
    text_elements = get_text_elements(tree)
    texts = [el.text or '' for el in text_elements]
    if not texts:
        return xml_bytes

    # Phase 1: handle relocation markers/blocks
    concat, starts = build_concat_and_starts(texts)
    start_marker='{{IF_RELOCATION}}'
    end_marker='{{END_IF_RELOCATION}}'
    matches=[]
    if start_marker in concat and end_marker in concat:
        if relocation_yes:
            # remove markers only
            idx=0
            while True:
                s=concat.find(start_marker, idx)
                if s==-1:
                    break
                matches.append((s, s+len(start_marker), ''))
                idx=s+len(start_marker)
            idx=0
            while True:
                s=concat.find(end_marker, idx)
                if s==-1:
                    break
                matches.append((s, s+len(end_marker), ''))
                idx=s+len(end_marker)
        else:
            idx=0
            while True:
                s=concat.find(start_marker, idx)
                if s==-1:
                    break
                e=concat.find(end_marker, s+len(start_marker))
                if e==-1:
                    break
                matches.append((s, e+len(end_marker), ''))
                idx=e+len(end_marker)
    if matches:
        apply_matches(texts, starts, matches)

    # Phase 2: placeholder replacements
    concat, starts = build_concat_and_starts(texts)
    matches=[]
    for key, val in replacements.items():
        placeholder='{{'+key+'}}'
        if placeholder not in concat:
            continue
        start=0
        while True:
            s=concat.find(placeholder, start)
            if s==-1:
                break
            matches.append((s, s+len(placeholder), val))
            start=s+len(placeholder)
    if matches:
        apply_matches(texts, starts, matches)

    # assign back
    for el, t in zip(text_elements, texts):
        el.text = t
    return ET.tostring(tree, encoding='utf-8')

relocation_yes = str(data.get('RELOCATION_PACKAGE','')).strip().lower() == 'yes'

with zipfile.ZipFile(src) as zin, zipfile.ZipFile(dst, 'w') as zout:
    for item in zin.infolist():
        data_bytes = zin.read(item.filename)
        if item.filename.startswith('word/') and item.filename.endswith('.xml'):
            try:
                new_bytes = process_xml(data_bytes, replacements, relocation_yes)
                zout.writestr(item, new_bytes)
            except Exception:
                # if parsing fails, write original
                zout.writestr(item, data_bytes)
        else:
            zout.writestr(item, data_bytes)

print('wrote', dst)
PY"}

